package com.tripmateai.controller; import com.tripmateai.dto.request.itinerary.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.itinerary.*; import com.tripmateai.service.ItineraryService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/trips/{tripId}/itineraries") @RequiredArgsConstructor public class ItineraryController {private final ItineraryService service; @PostMapping public ResponseEntity<ApiResponse<ItineraryResponse>> create(@PathVariable Long tripId,@Valid @RequestBody CreateItineraryRequest r){return ResponseUtils.created(service.create(tripId,r),"Itinerary created");} @GetMapping public ResponseEntity<ApiResponse<List<ItineraryResponse>>> list(@PathVariable Long tripId){return ResponseUtils.success(service.list(tripId),"Itineraries retrieved");} @GetMapping("/{id}") public ResponseEntity<ApiResponse<ItineraryResponse>> get(@PathVariable Long tripId,@PathVariable Long id){return ResponseUtils.success(service.get(tripId,id),"Itinerary retrieved");} @PutMapping("/{id}") public ResponseEntity<ApiResponse<ItineraryResponse>> update(@PathVariable Long tripId,@PathVariable Long id,@Valid @RequestBody UpdateItineraryRequest r){return ResponseUtils.success(service.update(tripId,id,r),"Itinerary updated");} @DeleteMapping("/{id}") public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long tripId,@PathVariable Long id){service.delete(tripId,id);return ResponseUtils.success(null,"Itinerary deleted");}}
